  "vidcfg.cfgScale": "CFG-Skala ({value})",
  "vidcfg.cfgScaleHint": "0 = kreativ, 1 = strikt am Prompt",
  "vidcfg.minimaxH3ResNote": "Ausgabe in 2K (Standard) oder 768P – 768P wird zum günstigeren Sekundenpreis abgerechnet. „Adaptiv“ übernimmt die verbundene Eingabe; reines Text-zu-Video wird in 16:9 gerendert, sofern kein bestimmtes Seitenverhältnis gewählt ist. Audio wird immer erstellt – lippensynchron zum Referenz-Audio, wenn eines verbunden ist.",
