  "vidcfg.switchxHelpSelect": "Gib ein Maskenbild für einen Keyframe vor (z. B. verbinde einen Node „Maske erstellen“ mit der Eingabe „Maske“); die KI überträgt es auf das ganze Video.",
  "vidcfg.switchxHelpCustom": "Gib ein vollständiges Alpha-Matte-Video pro Frame vor, um framegenau zu steuern.",
