  "vidcfg.descVeoUpscale": "Skaliert ein VEO-Video auf eine höhere Auflösung hoch. Verbinde einen vorgelagerten VEO-Video-Node.",
  "vidcfg.descSeedanceHdUpscale": "Rendert einen Seedance-2.5-Entwurf Frame für Frame als denselben Take in 1080p neu. Verbinde einen vorgelagerten Seedance-2.5-Node mit aktiviertem Entwurf. Der Preis richtet sich nach der Länge des Entwurfs.",
