  "vidcfg.minimaxH3ResNoteT2v": "Ausgabe in 2K (Standard) oder 768P – 768P wird zum günstigeren Sekundenpreis abgerechnet. Audio wird immer erstellt – lippensynchron zum Referenz-Audio, wenn eines verbunden ist.",
  "vidcfg.geminiOmniQuotaExceeded": "Zu viele Eingaben für Gemini Omni: Bilder + 2×Videos müssen ≤ 7 sein (aktuell {used}). Der Startframe und jedes Referenzbild zählen 1; jedes Quellvideo zählt 2. Entferne vor dem Erstellen einige Eingaben.",
