  "proccfg.editPlanOffsetHint": "Versatz: Sekunden, die jede Aufnahme nach der Master-Aufnahme begann (negativ = davor). Lass das Feld leer, um die Messung von „Audio synchronisieren“ zu nutzen, wenn dessen Versätze verbunden sind (sonst 0); ein eingegebener Wert hat immer Vorrang.",
  "proccfg.cameraSwitchHint": "Wählt anhand dessen, wer spricht, welche Kamera jeden Schnitt zeigt – der Ton ändert sich nie. Verbinde die EDL von „Schnittplan“ mit „EDL“ und ein Ergebnis von „Transkribieren“ mit Sprechererkennung mit „Transkript“, dann die EDL-Ausgabe mit „EDL anwenden“. Cloud-Funktion.",
