  "vidcfg.audioSoundtrack": "Ersten Clip als Soundtrack abspielen",
  "vidcfg.audioSoundtrackOnNote": "Der erste Clip wird zum Ton des Ergebnisses, und die Personen agieren dazu. Alle weiteren Clips sind Stimmproben. Er zählt als Referenzvideo, daher wird die Ausführung zum Preis für Referenzvideos berechnet.",
