  "vidcfg.generateAudioDefaultOn": "Audio erstellen (standardmäßig an)",
  "vidcfg.seedanceDraft": "Entwurf (480p)",
  "vidcfg.seedanceDraftHelp": "Ein Entwurf kostet so viel wie eine Ausführung in 480p. Wenn dir ein Take gefällt, finalisiere ihn mit „Video hochskalieren“ → Seedance 2.5 HD (aus Entwurf), um denselben Take in 1080p zu erhalten. Erst einen Entwurf zu machen lohnt sich, sobald eine direkte Ausführung in 1080p 2 oder mehr Versuche bräuchte. Entwürfe werden etwa 7 Tage aufbewahrt.",
  "vidcfg.seedanceDraftResolutionLocked": "Entwürfe werden in 480p gerendert. Schalte „Entwurf“ aus, um eine andere Auflösung zu wählen.",
  "vidcfg.seedanceDraftOff": "Volles Rendering",
  "vidcfg.seedanceDraftShort": "Entwurf 480p",
  "vidcfg.seedanceTaskType": "Referenzvideo verwenden als",
  "vidcfg.seedanceTaskTypeAuto": "Auto",
  "vidcfg.seedanceTaskTypeReference": "Referenz",
  "vidcfg.seedanceTaskTypeEdit": "Zu bearbeitendes Video",
  "vidcfg.seedanceTaskTypeExtend": "Zu verlängerndes Video (nur neues Material)",
  "vidcfg.seedanceTaskTypeEditLocked": "„Bearbeiten“ behält Format und Länge des Videos bei.",
  "vidcfg.seedanceTaskTypeExtendLocked": "„Verlängern“ behält das Format des Videos bei.",
  "vidcfg.seedanceTaskTypeEditNotApplied": "„Bearbeiten“ braucht ein Referenzvideo mit {min}–{max} Sekunden. Dieses wird wie mit „Auto“ ausgeführt.",
  "vidcfg.seedanceTaskTypeExtendAutoLength": "„Verlängern“ läuft mit {seconds} Sekunden, wenn „Dauer“ auf „Auto“ steht.",
  "vidcfg.v2vSeedanceEditHint": "Dein Prompt wird als „edit @video_1 as follows: …“ gesendet – das Ergebnis behält Länge und Seitenverhältnis des Ausgangsclips. Der Clip muss 4–30 Sekunden lang sein. Verbinde Bilder mit „Bildreferenzen“ und verweise auf sie als {image:1}, {image:2}…",
