  "vidcfg.overlapKeyframe": "Letzter Keyframe – Überlappung nachspielen, dann fortsetzen",
  "vidcfg.overlapLastFrame": "Letzter Frame – direkt am Ende fortsetzen",
  "vidcfg.smartCutContinuousKeyframes": "Gleicht nur durchgehende Einstellungen ab; bewusste Schnitte bleiben erhalten. Wird keine passende Übereinstimmung gefunden, werden keine Frames gekürzt. Eine erfolgreiche Übereinstimmung kann den Übergang leicht verkürzen.",
  "vidcfg.smartCut": "Intelligenter Schnitt (experimentell)",
  "vidcfg.cutBestPair": "Bestes Paar – PSNR-Abgleich an der Grenze (Standard)",
  "vidcfg.cutPrerollKeepNext": "Pre-Roll, nächstes behalten – Naht in der Überlappung verbergen",
  "vidcfg.cutPrerollKeepPrev": "Pre-Roll, vorheriges behalten – Original-Frames des vorherigen Segments behalten",
  "vidcfg.bestPairSearchWindow": "Suchfenster für bestes Paar (Frames)",
  "vidcfg.checkingVideo": "Video wird geprüft…",
  "vidcfg.orientImage": "Bild (Ausrichtung wie Bild{suffix})",
  "vidcfg.orientImageKlingSuffix": ", max. 10 s",
  "vidcfg.orientVideo": "Video (Ausrichtung wie Video{suffix})",
  "vidcfg.orientVideoKlingSuffix": ", max. 30 s",
  "vidcfg.normal": "Normal",
  "vidcfg.nsfwFilter": "NSFW-Inhaltsfilter",
  "vidcfg.nsfwFilterForced": "Von deinem Administrator festgelegt",
  "vidcfg.originalAudio": "Original-Audio",
  "vidcfg.pro1080p": "Pro (1080p)",
  "vidcfg.referenceMode": "Referenzmodus",
  "vidcfg.spicy": "Pikant",
  "vidcfg.standard720p": "Standard (720p)",
  "vidcfg.subtle": "Dezent",
  "vidcfg.choose": "Auswählen",
  "vidcfg.durationAutoFromClip": "Die Dauer wird automatisch aus dem Quellclip übernommen.",
  "vidcfg.drivingAudioLength": "Der Clip ist so lang wie sein Audio: {min}–{max} s (höchstens {short} s bei 1440p oder 48 / 50 fps). Ohne Startbild ist er 16:9.",
  "vidcfg.durationAuto": "Auto",
  "vidcfg.durationAutoHint": "Auto: Das Modell wählt die Länge (beim Bearbeiten eines Referenzvideos die Länge des Quellclips). Credits werden für den längsten Clip reserviert (beim Bearbeiten eines Referenzvideos: die aufgerundete Länge des längsten Referenzvideos plus eine Sekunde) und bis auf die gelieferte Länge zurückerstattet.",
  "vidcfg.wan3Note": "Der Preis richtet sich nach Länge und Auflösung; der Button „Ausführen“ zeigt den Preis der gewählten Länge. Umgebungsgeräusche werden mit dem Clip erstellt. „Adaptiv“ übernimmt die verbundene Eingabe; reines Text-zu-Video wird in 16:9 gerendert, sofern kein konkretes Verhältnis gewählt ist.",
  "vidcfg.wan3VideoRefLimits": "Wan 3.0 verlangt, dass jeder Quellclip 1–15 s lang ist, alle verbundenen Clips zusammen ≤ 15 s ergeben und Eingabe- plus Ausgabedauer ≤ 30 s bleiben. Das prüft der Anbieter erst bei der Ausführung des Auftrags, nicht vor dem Absenden.",
  "vidcfg.wan3AudioRefLimits": "Jede Audioreferenz muss 1–15 s lang sein (wird vor dem Absenden des Auftrags geprüft), und alle verbundenen Audios zusammen dürfen höchstens 15 s ergeben.",
  "vidcfg.viduQ4Note": "Der Preis richtet sich nach Länge und Auflösung; der Button „Ausführen“ zeigt den Preis der gewählten Länge. Ein Start-Frame allein animiert diesen Frame; verbundene Referenzbilder oder Audio schalten in den Referenzmodus, der einen Prompt braucht. Das Seitenverhältnis gilt nur für Ausführungen mit Referenzen – eine Ausführung mit Start-Frame behält die Form des Frames. Ton wird mit dem Clip erstellt.",
  "vidcfg.viduQ4AudioRefLimits": "Vidu Q4 akzeptiert nur MP3-Audio, 3–12 s pro Clip. Andere Formate oder Längen werden vor dem Absenden des Auftrags abgelehnt – wandle den Clip zuerst in MP3 um.",
  "vidcfg.modeKeyframes": "Keyframes – Start-Frame, Zwischen-Frames, End-Frame",
  "vidcfg.kling4FramesUsed": "{used} von {max} Frames für einen Clip von {seconds} s (Start + Zwischen-Frames + Ende).",
  "vidcfg.kling4FramesOverCap": "Zu viele Frames für einen Clip von {seconds} s: {used} von {max}. Entferne Frames oder verlängere den Clip – ab 9 s sind 10 möglich.",
  "vidcfg.grokVideo15FramesUsed": "{used} von {max} Zwischen-Frames für einen Clip von {seconds} s. Sie werden gleichmäßig über den Clip verteilt, einer pro voller Sekunde darin.",
  "vidcfg.grokVideo15FramesOverCap": "Ein Clip von {seconds} s nimmt {max} Zwischen-Frames auf (einen pro voller Sekunde darin, höchstens 4); die letzten {extra} werden weggelassen. Verlängere den Clip, um mehr zu verwenden.",
  "vidcfg.grokVideo15LoopNote": "Verbinde dasselbe Bild als Start- und End-Frame für einen nahtlosen Loop.",
  "vidcfg.startFrameOnlyResolution": "{model} nimmt bei {resolution} nur einen Start-Frame: kein End-Frame, kein Loop, keine Zwischen-Frames. Wähle {fallback} oder entferne den End-Frame und die Zwischen-Frames.",
  "vidcfg.inBetweenFrames": "Zwischen-Frames",
  "vidcfg.connectInBetweenFramesNote": "Bilder an der Eingabe „Bildreferenzen“ werden in dieser Reihenfolge zu Zwischen-Frames – zum Umsortieren ziehen. Bis zu {max}.",
  "vidcfg.keepOriginalSound": "Eigenen Ton der Referenzvideos behalten",
  "vidcfg.kling4Note": "Preis pro Sekunde nach Länge und Auflösung. Ein Referenzvideo fügt seine eigenen Sekunden hinzu – mindestens so viele wie der Clip. Verbundene Figuren werden zu benannten Motiven, die du als @Name schreiben kannst. Ton wird immer erstellt.",
  "vidcfg.kling4FlashNote": "Preis pro Sekunde nach Länge, in 720p. Ein Referenzvideo fügt seine eigenen Sekunden hinzu – mindestens so viele wie der Clip. Ein Start-Frame allein ist exakt der erste Frame; neben Referenzen kommt er zu ihnen hinzu. Verbundene Figuren werden zu benannten Motiven, die du als @Name schreiben kannst. Stimmreferenz N wird zur Stimme von Figur N, in der Reihenfolge ihrer Verbindung; eine Figur braucht 2 bis 4 Bilder, um eine Stimme zu tragen, sonst wird ihr Clip verworfen. Ton wird immer erstellt.",
  "vidcfg.pixverseV6MaxNote": "Preis pro Sekunde nach Länge und Qualität; Audio zu erstellen kostet mehr pro Sekunde und ist aktiv, solange du es nicht ausschaltest. Ein Start-Frame ist exakt der erste Frame, und der Clip übernimmt seine Form – das Seitenverhältnis gilt für reine Textausführungen. Kein End-Frame und keine Referenzeingaben.",
  "vidcfg.ltx25Note": "Ton (Dialog, Effekte, Atmosphäre) entsteht bei jedem Lauf mit dem Bild: Beschreibe ihn im Prompt. Text in Anführungszeichen wird gesprochen; schreibe \"Shot 1: … Shot 2: …\" für mehrere Einstellungen. Kein End-Frame und kein Negativ-Prompt.",
  "vidcfg.ltx25LongClipNote": "Bei 1440p oder 48/50 fps ist ein Clip höchstens {max} s lang.",
  "vidcfg.ltx25FrameShapeNote": "Der Start-Frame bestimmt das Format des Clips.",
  "vidcfg.kling4KeyframesNote": "Preis pro Sekunde nach Länge und Auflösung. Bildreferenzen sind die Zwischen-Frames, in Reihenfolge; die Länge des Clips begrenzt die Frames insgesamt (3 s → 4 … ab 9 s → 10). Das Seitenverhältnis gilt nur, wenn kein Frame verbunden ist. Ton wird immer erstellt.",
  "vidcfg.matchResSeam": "Die gleiche Auflösung wie das Quellvideo ergibt den saubersten Übergang.",
  "vidcfg.sameSeedSimilar": "Derselbe Seed liefert ähnliche Ergebnisse. Für einen zufälligen Wert leer lassen.",
