  "audiocfg.descPortraitTalkingHead": "Verbinde ein Porträtbild und eine Audiospur (Sprache/Voiceover), um ein Video mit sprechendem Porträt zu erstellen.",
  "audiocfg.descSingingDiffusion": "Verbinde ein Video und eine Audiospur. Ideal für Gesang – nutzt Diffusion für hochwertige Lippensynchronisation.",
  "audiocfg.descAvatarInference": "Verbinde ein Video und eine Audiospur, um die Sprache mit hochpräziser Lippensynchronisation per Avatar-Inferenz zu ersetzen oder zu synchronisieren. Abrechnung pro Sekunde Ausgabe.",
  "audiocfg.descStudioGrade": "Verbinde ein Video (.mp4) und eine Audiospur (.wav) für Lippensynchronisation in Studioqualität. Abrechnung pro Sekunde Ausgabe.",
  "audiocfg.descSyncSo": "Verbinde ein Video und eine Audiospur, um das Material mit sync.so v3 (fal.ai) zu synchronisieren. Abrechnung pro Sekunde Ausgabe.",
  "audiocfg.retiredLipSyncModel": "{model} ist für „Lippensynchronisation“ nicht mehr verfügbar. Wähle ein anderes Modell für die Lippensynchronisation.",
  "audiocfg.descVolcengine": "Verbinde ein Video und eine Audiospur, um das Material zu synchronisieren (Volcengine). Die Ausgabelänge folgt dem Audio. Abrechnung pro Sekunde.",
  "audiocfg.descVoiceExtractor": "Entfernt Hintergrundgeräusche und extrahiert eine saubere Stimme aus jeder Audioeingabe. Verbinde eine Audioquelle („Audio hochladen“, „Text zu Sprache“ usw.) mit der Eingabe.",
  "audiocfg.hintSpeakerBoostDesc": "Verstärkt den Vortrag der Quelle. Lass den Wert auf 0, außer du willst mehr Dramatik – höhere Werte erhöhen die Latenz und können die Stabilität verringern.",
  "audiocfg.hintSimilarityBoostDesc": "Verstärkt die Ähnlichkeit zur Zielstimme (braucht mehr Rechenleistung, leichte Latenz). Standardmäßig aktiviert.",
  "audiocfg.hintSeedReproducible": "Lege ihn fest für eine reproduzierbare Ausgabe (gleicher Seed + gleiche Eingabe + gleiche Einstellungen). Leer lassen für einen zufälligen Wert.",
  "audiocfg.hintDubCloneDesc": "Standardmäßig KLONT die Synchronisation den ursprünglichen Sprecher – er spricht die Zielsprache mit seiner eigenen Stimme und seinem Akzent. Aktiviere diese Option, um stattdessen eine ähnliche, muttersprachlich klingende Stimme zu verwenden.",
  "audiocfg.hintDubTranslate": "Übersetzt die Sprache in die Zielsprache. Verbinde eine Audioquelle mit der Eingabe.",
  "audiocfg.descVoiceDesign": "Erstellt eine neue Stimme aus einer Beschreibung in natürlicher Sprache und erzeugt eine Audiovorschau mit dem angegebenen Text.",
  "audiocfg.descForcedAlign": "Richtet Audio an einem Transkript aus und erzeugt Zeitstempel pro Wort. Verbinde eine Audioquelle mit der Eingabe.",
  "audiocfg.descRecast": "Sprecher werden automatisch erkannt. Mit Stimme 1 wird der Sprecher neu besetzt, der als Erster spricht, mit Stimme 2 der zweite und so weiter. Sprecher über das Ende dieser Liste hinaus behalten ihre ursprüngliche Stimme.",
  "audiocfg.hintPreservedMusicLevel": "Legt die Lautstärke der erhaltenen Hintergrundmusik im Verhältnis zu den neuen Stimmen fest.",
  "audiocfg.hintRevoiceOffOn": "Aus: Musik- und Soundeffekt-Bett unter der neuen Stimme behalten. Ein: saubere Ausgabe nur mit Stimme.",
  "audiocfg.hintRevoicePre": "Ersetzt die Stimme durch die ausgewählte und behält Emotion, Sprechrhythmus und Timing bei. Verbinde ",
  "audiocfg.hintRevoiceMid": " für eine Audioausgabe oder ",
  "audiocfg.hintRevoicePost": " zum Neuvertonen eines ganzen Sprechclips (du erhältst das Video samt neuer Audiospur zurück). Sind beide verbunden, hat das Video Vorrang und die Audioeingabe wird ignoriert.",
