  "tut.ccvInSub": "Ein Bild. Das ist die Szene.",
  "tut.ccvRefPromptEyebrow": "Referenz-Prompt",
  "tut.ccvBriefEyebrow": "Das Coverage-Briefing · bearbeite es, um den Plan zu ändern",
  "tut.ccvBriefRule1": "Echte Coverage-Reihenfolge: Totale, zwei halbnahe Einstellungen, zwei Großaufnahmen, Over-the-Shoulder, Gegenschuss, Detailaufnahme, dynamischer Kamerawinkel, Profil.",
  "tut.ccvBriefRule2": "Ein Kamerawinkel pro Zeile. Nie zwei Winkelbegriffe kombinieren.",
  "tut.ccvBriefRule3": "Kameraposition, keine Bewegung. Bewegung kommt später dazu.",
  "tut.ccvBriefRule4": "Die Blickrichtung bleibt konsistent, damit die Schnitte nicht springen.",
  "tut.ccvBriefRule5": "Lass Luft. Jedes Frame muss als Startframe für eine Animation taugen.",
