  "tut.promptEyebrow": "PROMPT",
  "tut.ocHeadline": "Zwei Bilder. Fünf Rezepte. Keine Masken, keine Ebenen.",
  "tut.ocSubline": "Jedes Rezept unten liest dieselben zwei Quellen. Was sich ändert, ist, welchen Teil jeder Quelle du nennst und unter welcher Nummer. Das ist die ganze Technik.",
  "tut.ocChipNoMask": "keine Masken",
  "tut.ocInTitle": "Zwei Quellen",
  "tut.ocInSub": "Eine erstellt, eine hochgeladen",
  "tut.ocRoleGenerated": "erstellte Laufsteg-Aufnahme",
  "tut.ocRoleUploaded": "hochgeladene Studioaufnahme",
  "tut.ocSameTwoEyebrow": "IMMER DIESELBEN ZWEI",
  "tut.ocSameTwoBody": "Alle fünf Rezepte sind mit diesen zwei Bildern verbunden. Zwischen den Ausführungen wird nichts neu hochgeladen und nichts bearbeitet.",
  "tut.ocRecipesTitle": "Fünf Rezepte",
  "tut.ocRecipesSub": "Je eine Zeile Prompt",
  "tut.ocRecipesMeta": "KLICKE AUF EINES",
  "tut.ocTakesEyebrow": "WAS DIESES REZEPT ÜBERNIMMT",
  "tut.ocNodeEyebrow": "NODE",
  "tut.ocR1Name": "Gesicht aus dem einen, Körper aus dem anderen",
  "tut.ocR1OutTitle": "Ein Körper, ein anderes Gesicht",
  "tut.ocR1OutSub": "Rezept 1 · beide Referenzen mit Qualifizierer",
  "tut.ocR1LessonKind": "DIE AUSGANGSBASIS",
  "tut.ocR1Lesson": "Zwei Referenzen mit Qualifizierer bauen aus zwei Bildern eine einzige Person. Keines kommt vollständig an.",
  "tut.ocR1Note1": "Pose, Statur und Bildausschnitt. Das Gesicht wird nicht verwendet.",
  "tut.ocR1Note2": "Nur das Gesicht wird übernommen.",
  "tut.ocR2Name": "Reihenfolge tauschen, Ergebnis tauschen",
