  "tut.ocR2OutSub": "Rezept 2 · Nummern vertauscht",
  "tut.ocR2LessonKind": "DER KERN DER GANZEN VORLAGE",
  "tut.ocR2Lesson": "Gleiche Qualifizierer, vertauschte Nummern. Welches Bild 1 und welches 2 ist, entscheidet, wer am Ende im Bild ist.",
  "tut.ocR2Note1": "Jetzt liefert die zweite Quelle den Körper.",
  "tut.ocR2Note2": "Und die erste liefert nur das Gesicht.",
  "tut.ocR3Name": "Bühne behalten, Star tauschen",
  "tut.ocR3OutTitle": "Gleicher Ort, andere Person",
  "tut.ocR3OutSub": "Rezept 3 · Qualifizierer background",
  "tut.ocR3LessonKind": "EIN ANDERER QUALIFIZIERER",
  "tut.ocR3Lesson": "background verlangt den Ort ohne die Person darin. Praktisch, wenn du den Schauplatz behalten willst.",
  "tut.ocR3Note1": "Der Laufsteg und seine Beleuchtung, ohne das Model.",
  "tut.ocR3Note2": "Die Person, die jetzt darauf steht.",
  "tut.ocR4Name": "Vom Laufsteg ins Studio",
  "tut.ocR4OutTitle": "Gleiche Person, anderer Ort",
  "tut.ocR4OutSub": "Rezept 4 · das Spiegelbild von Rezept 3",
  "tut.ocR4LessonKind": "ACHTE AUF DIE PRÄPOSITION",
  "tut.ocR4Lesson": "settings ist das Gegenstück zum Rezept darüber: Die Person bleibt, aber sie wird woanders hingesetzt. Das Wort in übernimmt die Platzierung.",
  "tut.ocR4Note1": "Das Motiv, vollständig übernommen.",
  "tut.ocR4Note2": "Der Studiohintergrund und sein Licht.",
  "tut.ocR5Name": "Ihre Jacke, ihr Studio, dein Model",
  "tut.ocR5OutTitle": "Drei Teile, zwei Bilder",
