  "tut.ocR5Lesson": "Dieselbe Quelle kann zweimal mit verschiedenen Qualifizierern genannt werden. Hier liefert Bild 2 in einer einzigen Zeile sowohl ein Kleidungsstück als auch einen Ort.",
