  "tut.regMrcSummary": "Fünf Quellbilder, ein erstelltes Bild. Zeig auf ein Bild, statt es zu beschreiben.",
  "tut.regMrcStep1Sub": "Fünf Uploads in einen Anschluss „Referenzen“",
