  "tut.regMrcStep4Sub": "Ein Bild tauschen, erneut ausführen, vergleichen",
  "tut.regWdSummary": "Aus einem Satz wurde ein Bild, aus dem Bild Bewegung, und eine Sprachzeile hat alles verbunden. Diese Arbeitsfläche ist eine abgeschlossene Ausführung.",
  "tut.regWdStep2Sub": "Z-Image, das Erste, das sich auszuführen lohnt",
  "tut.regWdStep3Sub": "Seedance 2 Fast, 5 Sekunden",
  "tut.regWdStep4Sub": "Eine zweite Kette, parallel ausgeführt",
  "tut.regWdStep5Sub": "Video und Stimme zusammengeführt",
  "tut.regPnTitle": "Erste Schritte mit dem Node „Person“",
  "tut.regPnSummary": "Wähle Attribute aus Dropdowns, und der Node schreibt den Figuren-Prompt für dich. Drei Ausführungen, von einem einzelnen Node bis zur vollen Kombination.",
  "tut.regPnChip": "3 Ausführungen",
  "tut.regSunoTitle": "Musik mit Nodes machen",
  "tut.regSunoSummary": "Du schreibst keine Songbeschreibung. Du wählst Optionen, und die Nodes schreiben sie für dich.",
  "tut.regSunoChip": "7 Ausführungen",
  "tut.regSunoNoteEyebrow": "So nutzt du dieses Tutorial",
  "tut.regSunoNoteBody": "Geh die Ausführungen nacheinander durch. Jede ändert genau eine Sache gegenüber der vorherigen, der Unterschied, den du hörst, ist also die geänderte Option.",
  "tut.regSunoStep1Title": "Wähle Optionen in den Stil-Nodes",
  "tut.regSunoStep1Sub": "Genre, Stimmung, Instrumentierung, Stimme",
  "tut.regSunoStep2Title": "Schick sie in den Node „Suno: Erstellen“",
  "tut.regSunoStep2Sub": "Die Auswahl wird zur Stilbeschreibung",
  "tut.regSunoStep3Title": "Erhalte einen fertigen Song",
  "tut.regSunoStep3Sub": "Hör ihn dir an und ändere dann eine Option",
  "tut.regApTitle": "Social-Media-Autopilot",
  "tut.regApSummary": "Füge eine Idee ein. Sieben Nodes teilen sie in Slides auf, erstellen zu jeder ein Bild, schreiben die Bildunterschrift und veröffentlichen den Beitrag.",
  "tut.regApStep1Title": "Gib einen einzigen Textblock ein",
  "tut.regApStep1Sub": "Sonst gibt es nichts auszufüllen",
  "tut.regApStep2Title": "Schreibt und gestaltet zehn Slides",
  "tut.regApStep2Sub": "Text pro Slide, je ein Bild",
  "tut.regApStep3Title": "Schreibt die Bildunterschrift und veröffentlicht",
  "tut.regApStep3Sub": "Für den Feed formatiert, dann veröffentlicht",
  "tut.regIedTitle": "Einstieg in die Bildbearbeitung",
  "tut.regIedSummary": "Ein Bild wird einmal erstellt, und neun unabhängige Bearbeitungen lesen jeweils dasselbe Original. Nichts baut aufeinander auf, also verschlechtert sich nichts.",
  "tut.regIedNoteEyebrow": "Eine Verzweigung, keine Kette",
  "tut.regIedNoteBody": "Jede Bearbeitung liest direkt das Original. Ändere eine, und die anderen acht bleiben unberührt – genau darum geht es.",
  "tut.regIedStep1Sub": "Einmal erstellt, dann bewertet",
  "tut.regIedStep2Title": "Neun Bearbeitungen, eine Quelle",
  "tut.regIedStep2Sub": "Jede liest dasselbe Bild",
  "tut.regIedStep3Title": "Verfolge jedes Ergebnis",
  "tut.regIedStep3Sub": "Klicke auf eine Kachel, um zu sehen, woraus sie entstanden ist",
  "tut.regCcvTitle": "Kamera-Coverage – ein Frame, zehn Blickwinkel",
  "tut.regCcvSummary": "Ein Referenz-Frame rein, zehn Einstellungen derselben Szene raus. Nur die Kamera ändert sich – ein Coverage-Plan wie vom Regisseur, den du zusammenschneiden kannst, aus einem einzigen Bild.",
  "tut.regCcvChip": "10 Einstellungen",
  "tut.regCcvNoteEyebrow": "Der Hebel ist die Liste",
  "tut.regCcvNoteBody": "Ein Bild-Node, zehn Zeilen. Die Liste verteilt ihn, sodass zehn Einstellungen sechs Nodes kosten statt fünfundzwanzig – und wer eine Zeile bearbeitet, dreht genau einen Blickwinkel neu.",
  "tut.regCcvStep1Sub": "Ein Bild und das Briefing, das den Plan bestimmt",
  "tut.regCcvStep2Sub": "Zehn Zeilen, die du lesen – und umschreiben – kannst, bevor du etwas ausgibst",
  "tut.regCcvStep3Sub": "Zehn Einstellungen eines Moments, aus einem Bild-Node",
  "tut.regOcTitle": "Eine Figur, jede Szene",
  "tut.regOcSummary": "Zwei Quellbilder, fünf einzeilige Rezepte, keine Masken und keine Ebenen. Was sich zwischen den Ergebnissen ändert, ist, welchen Teil jeder Quelle du nennst – und unter welcher Nummer.",
  "tut.regOcChip": "5 Rezepte",
  "tut.regOcNoteEyebrow": "Lies die Nummern, nicht die Bilder",
  "tut.regOcNoteBody": "{image:1} und {image:2} sind Positionen in der Referenzliste – die Reihenfolge, in der die Quellen verbunden wurden – und nicht die Namen der Nodes. Rezept 2 ist Rezept 1 mit vertauschten Nummern, und das ist die ganze Lektion.",
  "tut.regOcStep1Sub": "Eins erstellt, eins hochgeladen – {image:1} und {image:2}",
  "tut.regOcStep2Sub": "Klicke auf eins: was es aus jeder Quelle nimmt und was es lehrt",
  "tut.regOcStep3Sub": "Das Bild und wie sich die entliehenen Teile darin zusammenfügen",
  "tut.regUwTitle": "Unterwasserriesen",
  "tut.regUwSummary": "Schreibe acht Szenen. Jede wird zu einem Bild, dann zu einer fünfsekündigen Einstellung, mit Musik zusammengeschnitten und als Reel veröffentlicht.",
  "tut.regUwStep1Title": "Schreibe acht Szenen",
  "tut.regUwStep1Sub": "Je ein Absatz",
  "tut.regUwStep2Title": "Erst Standbilder, dann Bewegung",
  "tut.regUwStep2Sub": "Jede Szene knüpft an die vorige an",
  "tut.regUwStep3Title": "Vertont, geschnitten, veröffentlicht",
  "tut.regUwStep3Sub": "34 Sekunden, Hochformat",
