  "previewGate.headlessRefusal": "Dieser Workflow hält für eine Prüfung an, und das kann nur eine Ausführung, die im Nodaro-Editor oder auf der eigenen Seite einer App gestartet wurde. Öffne ihn dort, um ihn auszuführen, oder stelle jedes Rendering von „Vorschau“ auf „Final“ (oder sende dafür eine Qualitätsvorgabe „Final“) und schalte „Vor dem Rendern prüfen“ bei jedem Node aus, bei dem es aktiv ist.",
  "previewGate.headlessRefusalRender": "Dieser Workflow hält für eine Prüfung an: Sein Rendering steht auf „Vorschau“, und anhalten kann nur eine Ausführung, die im Nodaro-Editor oder auf der eigenen Seite einer App gestartet wurde. Öffne ihn dort, um ihn auszuführen, oder stelle das Rendering auf „Final“ (oder sende dafür eine Qualitätsvorgabe „Final“).",
  "previewGate.headlessRefusalReview": "Dieser Workflow hält für eine Prüfung an: Bei einem seiner Nodes ist „Vor dem Rendern prüfen“ aktiv, und anhalten kann nur eine Ausführung, die im Nodaro-Editor oder auf der eigenen Seite einer App gestartet wurde. Öffne ihn dort, um ihn auszuführen, oder schalte „Vor dem Rendern prüfen“ bei jedem Node aus, bei dem es aktiv ist.",
  "previewGate.nestedRefusal": "Dieser Sub-Workflow hält für eine Prüfung an, was ein verschachtelter Workflow nicht kann. Stelle jedes Rendering von „Vorschau“ auf „Final“ und schalte „Vor dem Rendern prüfen“ bei jedem Node aus, bei dem es aktiv ist.",
  "previewGate.nestedRefusalRender": "Dieser Sub-Workflow hält für eine Prüfung an (sein Rendering steht auf „Vorschau“), was ein verschachtelter Workflow nicht kann. Stelle dieses Rendering auf „Final“.",
  "previewGate.nestedRefusalReview": "Dieser Sub-Workflow hält für eine Prüfung an (bei einem seiner Nodes ist „Vor dem Rendern prüfen“ aktiv), was ein verschachtelter Workflow nicht kann. Schalte „Vor dem Rendern prüfen“ bei jedem Node aus, bei dem es aktiv ist.",
  "runContinuation.subsetRequired": "Diese Ausführung setzt eine frühere fort und muss daher die Nodes nennen, die sie ausführt. Alle anderen Nodes geben weiter, was die frühere Ausführung erzeugt hat.",
  "runContinuation.notFound": "Die fortzusetzende Ausführung wurde nicht gefunden oder gehört nicht dir.",
  "runContinuation.workflowMismatch": "Die fortzusetzende Ausführung gehört zu einem anderen Workflow.",
  "runContinuation.versionMismatch": "Die fortzusetzende Ausführung hat eine andere Version dieses Workflows ausgeführt (eine veröffentlichte App-Version oder den Workflow selbst). Setze eine Ausführung derselben Version fort.",
  "runContinuation.notCompleted": "Die fortzusetzende Ausführung ist nicht abgeschlossen. Warte, bis sie endet, oder setze eine abgeschlossene Ausführung fort.",
  "runContinuation.notFailed": "Die fortzusetzende Ausführung ist nicht fehlgeschlagen. Nur eine fehlgeschlagene Ausführung kann dort fortgesetzt werden, wo sie angehalten hat.",
  "runContinuation.superseded": "Eine spätere Fortsetzung dieser Ausführung ist fehlgeschlagen: Setze stattdessen diese fort.",
  "runContinuation.previewPending": "Eine spätere Fortsetzung dieser Ausführung hat bei ihrer Vorschau-Prüfung angehalten. Führe zuerst ihr finales Rendering aus und setze dann fort.",
  "runContinuation.alreadyRendered": "Mit dieser Bearbeitung bereits gerendert.",
  "runContinuation.nothingKept": "Bei der Prüfung wurden alle Clips verworfen: Behalte mindestens einen Clip, um die finale Version zu rendern.",
