  "runContinuation.settling": "Diese Ausführung wird noch abgerechnet und kann daher noch nicht fortgesetzt werden. Versuche es gleich noch einmal.",
  "continueFailed.action": "Ab Fehler fortsetzen",
  "continueFailed.actionTitle": "Die letzte Ausführung ist fehlgeschlagen. Setze sie dort fort, wo sie angehalten hat: Die abgeschlossenen Schritte bleiben erhalten, und alle anderen Schritte werden ausgeführt und berechnet, auch einer, den du seitdem selbst ausgeführt hast. Du siehst sie mit ihrem Preis, bevor etwas startet.",
