  "vidcfg.videoMaskRedetectValue": "{sec} s",
  "vidcfg.videoMaskRedetectHint": "Erkennt das Motiv außerdem alle paar Sekunden neu, sodass jemand, der mitten in einer Einstellung ins Bild kommt oder sich zur Kamera dreht, ab der nächsten Prüfung maskiert wird. Jede Prüfung ist eine weitere Anfrage an das Modell, daher dauert die Ausführung länger; der Preis bleibt gleich. Eine gehaltene Maske bleibt über diese Prüfungen hinweg erhalten (nur ein Schnitt beendet sie). 0 schaltet die Funktion aus.",
  "proccfg.maskCompositeDesc": "Legt das Vordergrundvideo über das Hintergrundvideo, gesteuert durch das Maskenvideo: Weiß zeigt den Vordergrund, Schwarz den Hintergrund. Das Ergebnis übernimmt Größe, Framerate und Länge des Vordergrunds und wird pro angefangene 5 Sekunden davon berechnet. Mit Verpixeln oder Weichzeichnen ist kein Vordergrund nötig, und das Ergebnis folgt dem Hintergrund.",
  "proccfg.maskCompositeInvert": "Maske umkehren",
  "proccfg.maskCompositeInvertHint": "Tauscht die Seiten: Weiß zeigt stattdessen den Hintergrund.",
  "proccfg.maskCompositeFeather": "Weiche Kante: {n} px",
  "proccfg.maskCompositeFeatherHint": "Macht die Maskenkante weicher. 0 behält eine harte Kante.",
  "proccfg.maskCompositeGrow": "Erweitern / verkleinern: {n} px",
  "proccfg.maskCompositeGrowHint": "Ein positiver Wert vergrößert die weiße Fläche, ein negativer verkleinert sie.",
  "proccfg.maskCompositeOpacity": "Deckkraft: {n} %",
  "proccfg.maskCompositeOpacityHint": "Wie stark die Füllung (der Vordergrund oder der verpixelte / weichgezeichnete Hintergrund) den Hintergrund innerhalb der Maske überdeckt. Bei 100 % ersetzt sie den Hintergrund dort; niedrigere Werte mischen beides.",
  "proccfg.maskCompositeFill": "Füllung",
  "proccfg.maskCompositeFillVideo": "Video (der Vordergrund)",
  "proccfg.maskCompositeFillPixelate": "Verpixeln",
  "proccfg.maskCompositeFillBlur": "Weichzeichnen",
  "proccfg.maskCompositeFillHint": "Was die maskierte Fläche füllt. Verpixeln und Weichzeichnen verwenden den Hintergrund selbst, daher ist kein Vordergrund nötig, und das Ergebnis übernimmt Größe, Framerate und Länge des Hintergrunds.",
  "proccfg.maskCompositePixelSizePct": "Blockgröße (% der Breite): {n} %",
  "proccfg.maskCompositePixelSizePctHint": "Die Größe jedes Blocks als Anteil an der Videobreite, damit es bei jeder Auflösung gleich aussieht. Größere Blöcke verbergen mehr Details.",
  "proccfg.maskCompositeBlurStrengthPct": "Weichzeichnung (% der Breite): {n} %",
